local ECSComponent = import("Frame.ECS.ECSComponent")

local CatHouseOtherHomeDojo = import("Game.Dojo.CatHouseOtherHomeDojo")

---@class CatHouseOtherPlayerComponent
local CatHouseOtherPlayerComponent = Class("CatHouseOtherPlayerComponent", ECSComponent)
---@type ConstantsCatHouse
local ConstantsCatHouse = import("Game.CatHouse.ConstantsCatHouse")
local CatStatus = ConstantsCatHouse.CatStatus
local checkNumber = checkNumber
function CatHouseOtherPlayerComponent:__init()
    self.name = "CatHouseOtherPlayerComponent"
    self._catHouseHomeDojo = {}
  
end

function CatHouseOtherPlayerComponent:__delete()
    self._catHouseHomeDojo = nil
end

function CatHouseOtherPlayerComponent:InitialDojo(data)
