---GetShowCats
---获取当前显示状态的猫
function CatHouseOtherPlayerComponent:GetShowCats()
    local t = {}
    if self._catHouseHomeDojo.catList then
        for i, v in pairs(self._catHouseHomeDojo.catList) do
            if checkNumber(v.isShow) == 1 and isNull(v.status[CatStatus.Hatching]) then
                ---过滤出成年猫 并且显示的
                table.insert(t, v)
            end
        end
    end
    local seqKeys = {}
    if #t > 0 then
        SortByMember(t, "id")
        for i, v in pairs(t) do
            table.insert(seqKeys, string.format('%s%s%s', tostring(v.id), tostring(v.age), tostring(v.isShow)))
        end
    end
    return t, seqKeys
end


return CatHouseOtherPlayerComponent